// Clear claims on todos whose leases have expired. Returns affected rows for reservation release.
func (q *Queries) ReclaimExpiredTodos(ctx context.Context, projectID int32) ([]ReclaimExpiredTodosRow, error) {
	rows, err := q.db.Query(ctx, reclaimExpiredTodos, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReclaimExpiredTodosRow
	for rows.Next() {
		var i ReclaimExpiredTodosRow
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.Text,
			&i.Title,
			&i.Description,
			&i.Key,
			&i.Persona,
			&i.Priority,
			&i.Status,
			&i.TargetType,
			&i.TargetID,
			&i.Kind,
			&i.IssueRef,
			&i.Blocked,
			&i.ClaimedBy,
			&i.ClaimedAt,
			&i.LeaseExpiresAt,
			&i.CreatedAt,
			&i.ResolvedAt,
			&i.ReopenCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

